import csv
import io


def parse_csv(raw_csv: str):
    if len(raw_csv) > csv.field_size_limit():
        csv.field_size_limit(len(raw_csv))

    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"')
    header = next(reader, None)
    if header is None:
        return {"columns": [], "rows": []}

    columns = [value.strip() for value in header]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    rows = list(reader)
    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)

    while len(columns) < width:
        base = "column_{}".format(len(columns) + 1)
        name = base
        suffix = 2
        while name in used:
            name = "{}_{}".format(base, suffix)
            suffix += 1
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
